// Zugleich Audit-Log aller Aktionen: wer, was, wann, mit welchem Ergebnis.
// Übergeordnete Läufe (Preset, Sammelaktion) fassen den Status ihrer Kinder zusammen.
// Gelöschte Presets und Schritte lassen die Läufe stehen (preset_id, preset_step_id werden NULL).
type ActionRun struct {
	ID uuid.UUID
	// Hierarchie: Preset-Lauf → Schritt-Lauf → Element-Läufe (bei Gruppen/Geräten)
	ParentID *uuid.UUID
	// gesetzt am Wurzel-Lauf eines Presets
	PresetID     *uuid.UUID
	PresetStepID *uuid.UUID
	// Ziel; bei Sammelaktion die Gruppe/das Gerät; NULL nur am Preset-Wurzel-Lauf
	ElementID *uuid.UUID
	// ausführende Quelle; NULL bei übergeordneten Läufen
	SourceID *uuid.UUID
	// start, stop, set, reboot, vxl.*; am Preset-Wurzel-Lauf: preset
	Action string
	// bei set: zu setzende Werte; bei trigger: Overrides nur für diesen Aufruf
	Params json.RawMessage
	Status ActionStatus
	// Snapshot: war der Lauf kritisch (Aktion oder ein gesetzter Schlüssel)
	Critical bool
	// Snapshot der Prüfbedingung, z.B. [{"fact": "bitrate", "op": "eq", "value": 20}] mit timeout_s
	Verify json.RawMessage
	// Antwort des Geräts, z.B. DeviceError mit Detail und abgelehnten Feldern
	Response json.RawMessage
	// Mensch oder Dienstkonto (API-Token)
	RequestedByID uuid.UUID
	RequestedAt   time.Time
	SentAt        *time.Time
	RespondedAt   *time.Time
	FinishedAt    *time.Time
}

type ApiToken struct {
	ID uuid.UUID
	// meist ein Dienstkonto
	UserID uuid.UUID
	Name   string
	// SHA-256 eines zufälligen Tokens; Klartext nur einmal bei Erstellung angezeigt
	TokenHash  string
	ExpiresAt  *time.Time
	RevokedAt  *time.Time
	LastUsedAt *time.Time
	CreatedAt  time.Time
}

// "user" ist in PostgreSQL reserviert, daher app_user.
type AppUser struct {
	ID uuid.UUID
	// in Go auf Kleinschreibung normalisiert
	Username    string
	DisplayName *string
	Email       *string
	// lokale Anmeldung (argon2id); NULL = nur externe Anmeldung
	PasswordHash *string
	// Dienstkonto: nur API-Tokens, keine interaktive Anmeldung
	IsService bool
	// Benutzer werden nie gelöscht, nur deaktiviert
	Disabled    bool
	CreatedAt   time.Time
	LastLoginAt *time.Time
}

// Alle Änderungen außer Aktionen; Aktionen stehen in action_run.
type AuditLog struct {
	ID uuid.UUID
	// NULL = Monika selbst
	ActorID *uuid.UUID
	At      time.Time
	// create | update | delete | login | login_failed
	Verb string
	// rule, preset, device_source, role, permission_grant, forward_target, ...
	ObjectType string
	ObjectID   *uuid.UUID
	// Geheimnisse geschwärzt
	Before json.RawMessage
	// Geheimnisse geschwärzt
	After json.RawMessage
}

// 1:1-Erweiterung von element (kind = device). Wie das Gerät erreicht wird, steht in device_source. Geräte werden nie hart gelöscht.
