// Hinweis: device_id = id beim Gerät erfordert, dass die id vor dem Insert
// vergeben wird (in Go erzeugen statt per Default).
type Element struct {
	ID uuid.UUID
	// device, group, module, port, network_interface, clock, sender, receiver, peer, tunnel, processing, sensor, trigger
	Kind string
	// nur physische/strukturelle Hierarchie
	ParentID *uuid.UUID
	// zugehöriges Gerät; beim Gerät selbst = eigene id; NULL bei Gruppen
	DeviceID *uuid.UUID
	// besitzende Quelle; NULL bei Gerät und Gruppe
	SourceID *uuid.UUID
	// stabile ID innerhalb des Geräts, z.B. Slot-Pfad oder UnitID
	ExternalID *string
	// global eindeutige ID (XLink-UnitID, NMOS-UUID). Nur am Element im eigenen Baum, nie an Stellvertretern
	GlobalRef *string
	// sdi, madi, analog, aes3, st2110-20, st2110-30, st2110-40, aes67, xlink, srt, ndi, ...
	Transport *string
	// Fähigkeit des Anschlusses; die aktuelle Richtung steht in den Fakten
	Direction *PortDirection
	// Name, wie das Gerät ihn meldet
	Name *string
	// statische Treiber-Attribute, nur zur Anzeige
	Attributes json.RawMessage
	// Sortierung innerhalb des Parents
	Position *int32
	// unterstützte Befehle, z.B. {start,stop,reboot,vxl.reset_video_buffer}
	Actions []string
	// schreibbare Fakt-Schlüssel mit Typ, Grenzen und optional critical, z.B. {"bitrate": {"type": "int", "min": 1, "max": 100}, "eth0.ip": {"type": "ipv4", "critical": true}}
	Settings json.RawMessage
	// false = verschwunden oder noch nie gesehen; Zeile bleibt erhalten
	Present bool
	// NULL = vom User vorab angelegt, vom Treiber noch nie gesehen
	FirstSeenAt *time.Time
	LastSeenAt  *time.Time
	Label       *string
	Notes       *string
	// false = von allen Regeln ausgenommen (unbenutzt)
	Monitored bool
	CreatedAt time.Time
	UpdatedAt time.Time
}

// Regeln:
//   - Treiber-Links (feeds, uses, represents) werden bei Wegfall gelöscht,
//     nicht weich markiert; ihre Historie gehört nach InfluxDB/Audit.
//   - Ein Link über Gerätegrenzen wird von der Seite gemeldet, die ihn
//     konfiguriert (bei XLink: der Decoder).
//   - member-Links dürfen keine Zyklen bilden (Prüfung in der Anwendung).
//   - element_link_uq: keine doppelten Links, auch solange unaufgelöst.
type ElementLink struct {
	ID   uuid.UUID
	Type LinkType
	// meldende Quelle; NULL = vom User (member)
	SourceID *uuid.UUID
	FromID   *uuid.UUID
	// global_ref der Quelle, solange nicht aufgelöst
	FromRef *string
	ToID    *uuid.UUID
	// global_ref des Ziels, solange nicht aufgelöst
	ToRef *string
	// Position in der Gruppe, z.B. Stagebox-Kanal 5
	Position *int32
	// Label in diesem Kontext
	Label     *string
	CreatedAt time.Time
}

type ElementState struct {
	ElementID uuid.UUID
	// flache Map aller aktuellen Werte, z.B. {"running": true, "format.rate": 50}
	Facts json.RawMessage
	// vom Gerät gemeldete Alarme → automatisch Befunde
	Alarms json.RawMessage
	// vom Core: schlimmster aktiver Befund am Element
	Health Health
	// nur Gerät/Gruppe: {"ok": 12, "warning": 1, "error": 0, "unknown": 3}
	Rollup json.RawMessage
	// Zeitpunkt der Messung am Gerät
	ReportedAt *time.Time
	// Zeitpunkt des Schreibens
	UpdatedAt time.Time
}

// Höchstens ein aktiver Befund pro Element, Code und Regel. DBML kennt keine
// Teilindizes; finding_active_uq steht deshalb in migrations/00002_finding_active_uq.sql.
type Finding struct {
	ID        uuid.UUID
	ElementID uuid.UUID
	Origin    FindingOrigin
	// bei origin = rule; wird beim Löschen der Regel NULL, damit die Historie bleibt
	RuleID *uuid.UUID
	// rule: rule.violated · device: Alarmcode des Geräts · system: source.unreachable, data.stale
	Code     string
	Severity Severity
	// lesbarer Text, inkl. Regelname zum Zeitpunkt des Befunds
	Message *string
	// Sollwert, Istwert, Regel-Snapshot
	Details json.RawMessage
	// NULL = Ursache, sonst Symptom
	CausedByID *uuid.UUID
	RaisedAt   time.Time
	// NULL = aktiv
	ClearedAt *time.Time
	// Quittierung ändert nicht die Health, nur Anzeige und Meldung
	AckedAt   *time.Time
	AckedByID *uuid.UUID
}

